  return @(Get-CimInstance Win32_PnPSignedDriver | Where-Object DeviceID | Sort-Object DeviceID | Select-Object -First 5 | ForEach-Object {
    [pscustomobject]@{DeviceID=[string]$_.DeviceID;DeviceName=[string]$_.DeviceName;Version=[string]$_.DriverVersion;Signed=[bool]$_.IsSigned}
  })
}
$update=Get-Service wuauserv
$data=[pscustomobject]@{Drivers=@(Get-FndDrivers);Hotfixes=@(Get-CimInstance Win32_QuickFixEngineering | ForEach-Object {[string]$_.HotFixID} | Sort-Object);UpdateService=$update.Name;ObservedServiceStatus=$update.Status.ToString()}
[pscustomobject]@{Schema=1;LabId=$labId;Computer=$env:COMPUTERNAME;CollectedAtUtc=[DateTimeOffset]::UtcNow.ToString('o');Data=$data} | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $labRoot 'step2.json') -Encoding UTF8
Write-Output 'Da ghi step2.json; mo tep trong thu muc bai de doi chieu.'
